script.script:
try {
    // Get the admin user using jenkins.model.Jenkins
    def user = jenkins.model.Jenkins.get().getUser('admin')
    def tokenProperty = user.getProperty(jenkins.security.ApiTokenProperty.class)

    // Generate new token
    def result = tokenProperty.tokenStore.generateNewToken('gitops-script-token')
    def token = result.plainValue

    // Create a proper EnvironmentContributingAction
    def envAction = new hudson.model.EnvironmentContributingAction() {
        @Override
        void buildEnvironment(hudson.model.Run<?, ?> run, hudson.EnvVars env) {
            env.put('JENKINS_API_TOKEN', token)
        }

        @Override
        String getDisplayName() {
            return null
        }

        @Override
        String getIconFileName() {
            return null
        }

        @Override
        String getUrlName() {
            return null
        }
    }

    // Add the action to the build
    build.addAction(envAction)

    println "Token generated successfully and set as JENKINS_API_TOKEN: ${token}"
    return 0

} catch (Exception e) {
    println "Error generating token: ${e.message}"
    e.printStackTrace()
    return 1
}
